const updateTrainingMaterial = `-- name: UpdateTrainingMaterial :exec
UPDATE tbl_training_materials
SET
	title = ?1,
	description = ?2,
	url = ?3,
	embed_url = ?4,
	source_type = ?5,
	video_id = ?6,
	thumbnail_url = ?7,
	status = ?8,
	required = ?9,
	deleted_at = CASE
		WHEN ?8 = 'deleted' AND deleted_at IS NULL THEN datetime('now')
		WHEN ?8 = 'draft' OR ?8 = 'published' THEN NULL
		ELSE deleted_at
	END,
	updated_at = datetime('now')
WHERE id = ?10
`

type UpdateTrainingMaterialParams struct {
	Title        string
	Description  string
	Url          string
	EmbedUrl     string
	SourceType   string
	VideoID      string
	ThumbnailUrl string
	Status       string
	Required     int64
	ID           int64
}

