const upsertTrainingMaterialProgress = `-- name: UpsertTrainingMaterialProgress :exec
INSERT INTO tbl_training_material_progress (
	material_id,
	teacher_id,
	watch_seconds,
	progress_percent,
	completed_at,
	first_viewed_at,
	last_viewed_at
)
VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))
ON CONFLICT(material_id, teacher_id) DO UPDATE SET
	watch_seconds = excluded.watch_seconds,
	progress_percent = excluded.progress_percent,
	completed_at = CASE
		WHEN tbl_training_material_progress.completed_at IS NOT NULL THEN tbl_training_material_progress.completed_at
		WHEN excluded.completed_at IS NOT NULL THEN excluded.completed_at
		ELSE NULL
	END,
	last_viewed_at = datetime('now')
`

type UpsertTrainingMaterialProgressParams struct {
	MaterialID      int64
	TeacherID       int64
	WatchSeconds    int64
	ProgressPercent float64
	CompletedAt     sql.NullString
}

func (q *Queries) UpsertTrainingMaterialProgress(ctx context.Context, arg UpsertTrainingMaterialProgressParams) error {
	_, err := q.db.ExecContext(ctx, upsertTrainingMaterialProgress,
		arg.MaterialID,
		arg.TeacherID,
		arg.WatchSeconds,
		arg.ProgressPercent,
		arg.CompletedAt,
	)
	return err
}
